  FT["BN-S-100-1959-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CON-60B31D"] = {"id":"BN-S-100-1959-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CON-60B31D","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":2,"structureMode":"SECTION","title":{"zh":"宪法（职能移交与相应规定）第 2 号命令 1959","en":"CONSTITUTION TRANSFER OF FUNCTIONS AND CONSEQUENTIAL PROVISIONS NO. 2 ORDER 1959","orig":"CONSTITUTION TRANSFER OF FUNCTIONS AND CONSEQUENTIAL PROVISIONS NO. 2 ORDER 1959","vi":"Sắc lệnh chuyển giao chức năng và các quy định kèm theo của Hiến pháp số 2 năm 1959","th":"คำสั่งการโอนหน้าที่และบทบัญญัติที่เกี่ยวข้องตามรัฐธรรมนูญ ฉบับที่ 2 พ.ศ. 2502","id":"Perintah Pengalihan Fungsi dan Ketentuan Konsekuensial menurut Konstitusi Nomor 2 Tahun 1959","ms":"Perintah Pemindahan Fungsi dan Peruntukan Bersampingan di bawah Perlembagaan Bilangan 2 1959"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-100-1959-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONSEQUENTIAL-PROVISIONS-NO.-2-ORDER-1959.pdf》（1 页），本次切分 2 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-100-1959-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONSEQUENTIAL-PROVISIONS-NO.-2-ORDER-1959.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-100-1959-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CON-60B31D-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Every reference in any written law to the Council of State shall be construed as a reference to the Legislative Council."}},{"id":"BN-S-100-1959-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CON-60B31D-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"For the reference to the State Council in subsection (3) of section 244 of the Criminal Procedure Code, there shall be substituted a reference to the Privy Council.\n\nSCHEDULE (Article 3) Education Enactment, 1952 (No 2 of 195:!) section 29 (2) Consular Conventions Enactment, 1953 (No. 3 of 1953) . . . section 9 (4) Customs Enactment, l Q54 (No. 5 of 1954)... section 8 (3) Road Traffic Enactment, 1954 (No. 12 of 1954) section 85 (5) and (6) Made this 29th day of September, 1959, at Our Istana Darul Hana, Brunei, Darul Salam.\n\nOMAR ALI SAIFUDDIN Sultan"}}],"pack":"bn-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"CONSTITUTION TRANSFER OF FUNCTIONS AND CONSEQUENTIAL PROVISIONS NO. 2 ORDER 1959","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-103-1959-CONSTITUTION-ADMINISTRATIVE-APPEALS-RULES-2B3846"] = {"id":"BN-S-103-1959-CONSTITUTION-ADMINISTRATIVE-APPEALS-RULES-2B3846","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":1,"structureMode":"WHOLE","title":{"zh":"宪法行政上诉规则命令 1959","en":"CONSTITUTION ADMINISTRATIVE APPEALS RULES ORDER 1959","orig":"CONSTITUTION ADMINISTRATIVE APPEALS RULES ORDER 1959","vi":"Quy tắc Hiến pháp: kháng nghị hành chính năm 1959","th":"ข้อกำหนดรัฐธรรมนูญ: การอุทธรณ์ทางปกครอง พ.ศ. 2502","id":"Peraturan Konstitusi: Banding Administratif Tahun 1959","ms":"Kaedah Perlembagaan: Rayuan Pentadbiran 1959"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-103-1959-CONSTITUTION-ADMINISTRATIVE-APPEALS-RULES-ORDER-1959.pdf》（4 页），本次切分 1 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-103-1959-CONSTITUTION-ADMINISTRATIVE-APPEALS-RULES-ORDER-1959.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-103-1959-CONSTITUTION-ADMINISTRATIVE-APPEALS-RULES-2B3846-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"No. S. 103-\n\nTHE CONSTITUTION OF THE STATE OF\n\nBRUNEI, 1959 THE CONSTITUTION (ADMINISTRATIVE APPEALS RULES) ORDER, 1959 (Made under section 80) In exercise of the powers conferred on him by section 80 of the Constitution of the State of Brunei, 1959, the Sultan has made the following OrderCitation. 1. (1) This Order may be cited as the Consticommencement tution (Administrative Appeals Rules) Order, 1959, and application. and shall come into force on the same day as Part V of the Constitution.\n\n(2) Notwithstanding anything in any other written law contained, wherever, in any written law, provision is made for an appeal to the Sultan in Council otherwise than by petition(a) this Order shall apply to the extent that specific provision is not contained in such written law;\n\n(b) nothing therein contained shall be deemed to prevent any person from applying to the High Court for a mandamus, injunction, prohibition or any other order should he elect to do so, instead of appealing to the Sultan in Council, but no proceedings by way of mandan1us, injunction, prohibition or other order shall be taken against the Sultan in Council in respect of any such provision; and\n\n(c) every order of the Sultan in Council on any appeal under such provision shall be final and may be enforced by the High Court as if it had been an order of that court. Interpretation. 2. In this Order\"applicant\" means the person who initiates an appeal to the Sultan in Council; \"Clerk\" means Clerk to the Executive Council; \"Constitution'' means the Constitution of the State of Brunei, 1959; \"respondent\" means any public servant who is concerned in such an appeal and, where no such person is specified in any written law, means the head of any department which is concerned; \"written law\" means a written law in which an appeal to the Sultan in Council is provided. No appeal in 3. No appeal shall lie if proceedings have certain cases. already been taken or initiated before the High Court or a magistrate in respect of the matter of the appeal. Grounds of 4. A person may appeal whoappeal. (a) is dissatisfied with the exercise of the discretion of any person to whom discretionary power is given under a written law in respect of any act, matter or thing which is, by the written law, made subject to the exercise of the discretion of such authority;\n\n(b) is dissatisfied with any action or decision of any such person, either as to the carrying out of or the meaning of any of the provisions of the written law; or\n\n(c) considers that any of the provisions _of the written law are, owing to special conditions, undesirable. Statement of 5. The grounds of such appeal shall be congrounds of appeal cisely stated in writing in the Malay or English in writing. language, and shall be delivered to the Clerk for transmission to the Sultan in Council. Discretion of 6. The Sultan in Council maySultan in Council (a) require the respondent to give his reasons as to obtaining further for the exercise of his discretion, or for information. the action or decision, as the case may be, and to supply any further information which the Sultan in Council may require, including the record of any proceeding or hearing held in pursuance of any such written law; and\n\n(b) make or cause to be made .such other inquiries as he may deem necessary or expedient. Notice of hearing. 7. The Clerk shall, upon the direction of the Sultan in Council, give the applicant seven days' notice of the hearing of the appeal, and shall at the same time furnish the applicant with a copy of this Order. Appearance. 8. The applicant may, if he so desires~ be present at the hearing of such appeal and be heard in its support either in person or by his representative: Provided that, if he elects to be heard by his representative, he shall not himself be heard except by special leave of the Sultan in Council. Committee of 9. It shall be lawful for the Sultan in Council Executive Council. to appoint a committee consisting of members of the Executive Council for the purpose of hearing any such appeal and of advising him as to the decision that should be made thereon: Provided that the Sultan in Council shall not be bound to accept such advice. Power to make 10. (1) If, in the opinion of the Sultan in such order as may Council, the exercise of such discretion, or such be just. action or decision, requires modification, revocation or setting aside, or such special conditions exist as render any such provision undesirable, he may make such order in respect thereof as may be just.\n\n(2) In such event, or if the appeal be dismissed, the applicant shall be informed of such order or such dismissal by the Clerk in writing within fourteen days of the determination of the appeal, or within such time and in such manner as the Sultan in Council shall otherwise specify. Case stated. 11. ( 1) In any appeal, the Sultan in Council may at any time, in his discretion, direct a case to be stated for the opinion of the Court of Appeal on any question of law involved in any appeal submitted to him.\n\n(2) The terms of any such case shall be agreed upon by the parties concerned or, in the event of their failure to agree, shall be settled by the Court of Appeal.\n\n(3) The Court of Appeal shall hear and determine the question of law arising on any case stated as aforesaid, and shall remit the matter to the Sultan in Council who shall give effect by Order to the finding of the Court. The costs of such hearing shall be in the discretion of the Court.\n\n(4) Any party to the appeal shall be entitled to be represented by an advocate or appear !n person at the hearing of any case so stated. Made this 29th day of September, 1959, at Our Istana Darul Hana, Brunei, Darul-Salam.\n\nOMAR ALI SAIFUDDIN Sultan"}}],"pack":"bn-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"CONSTITUTION ADMINISTRATIVE APPEALS RULES ORDER 1959","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010"] = {"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":19,"structureMode":"SECTION","title":{"zh":"货币与金融修正命令 2010","en":"CURRENCY AND MONETARY AMENDMENT ORDER 2010","orig":"CURRENCY AND MONETARY AMENDMENT ORDER 2010","vi":"Sắc lệnh sửa đổi Sắc lệnh Tiền tệ và tài chính tiền tệ năm 2010","th":"คำสั่งแก้ไขเพิ่มเติมคำสั่งสกุลเงินและการเงิน พ.ศ. 2553","id":"Perintah Perubahan Perintah Mata Uang dan Moneter Tahun 2010","ms":"Perintah Pindaan Perintah Mata Wang dan Kewangan 2010"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010.pdf》（10 页），本次切分 19 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 1 of the Currency and Monetary Order, 2004, in this Order referred to as the principal Order, is amended - {a) in subsection (1), by deleting \"and Monetary\" from the first line; and {b) in subsection (2), by deleting \"a Brunei Currency and Monetary Board,\" from the first 2 lines. of section 2."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 2 of the principal Order is amended - {a) by inserting the following new definition immediately before the definition of \"bank\" 11 the Autoriti Monetari Brunei Darussalam by section 3 of the Autoriti Monetari Brunei Darussalam {b) by deleting the definition of \"bank\" and by substituting the new definition therefor \"\"bank\" means a bank licensed under sections 4 or 23 of the Banking (S 45/06) and an Islamic bank licensed under sections 4 or 23 of the Islamic Banking Order, 2008 (S 96/08);\"; {c) by deleting the definitions of \"Board\" and \"Chief Executive Officer\"; (dJ by inserting the following new definition immediately before the \"demand liabilities\" - means currency notes and coins which are legal tender in Brunei Darussalam;\"; (eJ by deleting the definition of \"member\". of Part II."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Part II of the principal Order is amended in the heading, by deleting \"BRUNEI AND MONETARY BOARD\" and by substituting \"TRANSFER OF FUNCTIONS, LIABILITIES AND EMPLOYEES TO AUTHORITY\" therefor. of section 3."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 3 of the principal Order is repealed and the following new section thereforto administer Order."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section 4 of the principal Order is repealed and the following new section therefor - to Authority of property, assets and liabilities."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section 5 of the principal Order is repealed and the following new section therefor of employees."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section 6 of the principal Order is repealed and the following new section substituted therefor - nservice rights etc. of transferred employees to be preserved."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section 7 of the principal Order is repealed and the following new section substituted therefor - \"Existing contracts."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section 8 of the principal Order is repealed and the following new section substituted therefor - \"Continuation and completion of disciplinary proceedings."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section 9 of the principal Order is repealed and the following new section substituted therefor - or neglect of duty by employee before transfer."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section 10 of the principal Order is repealed and the following new section substituted therefor \"Interpretation of this Part."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Section 11 of the principal Order is repealed. of new section 13A."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The principal Order is amended by inserting the following new section immediately after section 13 - to buy and sell currency notes and coins. 13A. (1) The Authority may, in its discretion, buy and sell currency notes and coins against gold, silver or foreign currencies eligible for inclusion in the reserve of the external assets specified under section 24.\n\n(2) The Authority shall be entitled to charge a commission at such rate or rates as maybe determined for any currency notes or coins bought or sold by the Authority under this section\". of section 23."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Section 23 of the principal Order is repealed and the following new section substituted therefor - Fund."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Section 24 of the principal Order is amended(a) in subsection ( 1) - (i} by deleting \"The external assets of the Board shall consist of all or any of the following\" from the first 2 lines and by substituting \"The external assets of the Currency Fund shall any of the following and shall at all times be than 100 per cent of the face value of the currency by the Authority\" therefor;\n\n(ii) in paragraph fa), by deleting \"coin and bullion\" and by substituting \"and silver in any form\" therefor;\n\n(b) in subsection (2) -\n\n(i) by deleting \"70\" from the second line and by substituting \"100\"\n\n(ii) in the proviso, by deleting \"figure of 70 per cent\" from the line and by substituting \"percentage\" therefor; {c) in subsection (5), in paragraph {b), by deleting \"subsection (5) of the last line and by substituting \"the accounting standards adopted by the Authority\" therefor. Repeal of sections 25 to 34."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Sections 25 to 34 of the principal Order are repealed. Amendment of principal Order."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"The principal Order is amended by deleting \"Board\" wherever that word appears, except in Part II, and by substituting \"Authority\" therefor. Savings and transitional provisions."}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"(1) On the appointed dayfa) the Brunei Currency and Monetary Board (referred to in this section as the Board) shall be dissolved;\n\n(b) currency notes and coins issued by the Board before the appointed day shall for all purposes be deemed to have been issued by the Autoriti Brunei Darussalam (referred to in this section as the Authority); and {c) all assets and moneys of the Reserve Fund shall be transferred to the Currency Fund.\n\n(2) Any decision made by the Board under the Order before the appointed day shall be deemed to be a decision made by the Authority.\n\n(3) Any permission, consent, approval or authorisation granted by the Board the Order before the appointed day shall, so far as it is not inconsistent with the provisions of the Order (as amended by this Order), be deemed to be a permission, consent, approval or authorisation granted by the Authority.\n\n(4) Any certificate, notice, order, direction or declaration issued or made by the Board or an officer of the Board under the Order before the appointed day be deemed to be a certificate, notice, order, direction or declaration issued or made by the Authority or an officer of the Authority.\n\n(5) Where there are any accounts of the Brunei Currency and Monetary which on the appointed day had not been audited by the Auditor General section 33 of the Currency and Monetary Order, 2004 (S 16/04) (repealed by (a} the Auditor General shall audit such accounts or cause such accounts to be audited;\n\n(b) such audited accounts shall be signed by the managing director and one other director of the board of directors of the Authority; and {c} the Authority shall thereafter transmit copies of such signed audited the Minister who shall then transmit the copies to His Majesty the Sultan and Yang Di-Pertuan.\n\n(6) in any document any reference is made to the Brunei Currency and Monetary Board such reference shall, as from the appointed day, be read as the Autoriti Monetari Brunei Darussalam.\n\n(7) The Minister may, with the approval of His Majesty the Sultan andY ang by order published in the Gazette, make such other savings or transitional provisions which appear to him to be necessary or expedient for the purposes of the Currency and Monetary (Amendment) Order, 2010.\n\n(8) In this section, \"appointed day\" means the date of commencement of the and Monetary (Amendment) Order, 2010. day of Muharram, 1432 Hjjriah corresponding to the 14th. day of December, 2010 at Our Istana Nurul Iman, Bandar Seri Begawan, Brunei Darussalam.\n\nTHE SULTAN AND YANG DI-PERTUAN\n\nBRUNEI DARUSSALAM"}},{"id":"BN-S-104-2010-CURRENCY-AND-MONETARY-AMENDMENT-ORDER-2010-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"(1) The Authority shall establish a Currency Fund which shall be and managed by the Authority in the manner prescribed in this\n\n(2) There shall be paid into the Currency Fund(a) all gold, silver and foreign currencies bought by the Authority section 13A of this Order; and\n\n(b) the proceeds of any transactions under subsection (6J(b), less all expenses incurred in connection therewith.\n\n(3) The Authority may charge on the Currency Fund any expense properly incurred by or on behalf of the Authority in connection with the execution of its functions under this Order, including expenses relating to(a) the investment of the Currency Fund;\n\n(b) the issue and demonetisation of currency notes and coins and the transaction of any business relating to such currency; and\n\n(c) the protection of currency notes and coins against forgery or counterfeiting.\n\n(4) Subject to this Order, the Currency Fund shall not be applied for any other purpose.\n\n(5) The Authority shall maintain adequate liquidity in the Currency Fund to meet all demands under normal market conditions.\n\n(6) Notwithstanding anything in subsections (1) to (4), the Authority may(a) use any coin held for the account of the Currency Fund for the of having it reminted into current coin; and\n\n(b) sell any coin held for the account of the Currency Fund.\n\n(7) The value of the Currency Fund and its assets for any purpose of this Order shall be determined by such method as the Authority may adopt.\n\n(8) If at any time the value of the Currency Fund determined by the under subsection (7) exceeds 100 per cent of the face value of the currency notes and coins then in circulation, the Authority may that the whole or part of such excess be transferred from the Currency Fund to the other funds of the Authority.\n\n(9) If at any time the face value of the Authority's currency notes and coins in circulation exceeds the value of the Currency Fund, the deficiency be made up from the other funds of the Authority and, if such funds are the balance of the deficiency shall be charged on and paid out of the Consolidated Fund.\n\n(10) In preparing the financial statements relating to the Currency Fund, the Authority may comply with accounting standards to the extent that it is, in the opinion of the Authority, appropriate to do so, having regard to the objects and functions of the Authority under this Order or the Autoriti Monetari Brunei Darussalam Order, 2010.\". of section 24."}}],"pack":"bn-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"CURRENCY AND MONETARY AMENDMENT ORDER 2010","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
