  FT["BN-S-15-2003-E-PERBADANAN-TABUNG-AMANAH-ISLAM-BRUNEI-ACT-4D698A"] = {"id":"BN-S-15-2003-E-PERBADANAN-TABUNG-AMANAH-ISLAM-BRUNEI-ACT-4D698A","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":2,"structureMode":"SECTION","title":{"zh":"文莱伊斯兰信托基金机构法修正命令 2003","en":"PERBADANAN TABUNG AMANAH ISLAM BRUNEI ACT AMENDMENT ORDER 2003","orig":"PERBADANAN TABUNG AMANAH ISLAM BRUNEI ACT AMENDMENT ORDER 2003","vi":"Sắc lệnh sửa đổi Luật Perbadanan Tabung Amanah Islam Brunei năm 2003","th":"คำสั่งแก้ไขเพิ่มเติมพระราชบัญญัติPerbadanan Tabung Amanah Islam Brunei พ.ศ. 2546","id":"Perintah Perubahan Undang-Undang Perbadanan Tabung Amanah Islam Brunei Tahun 2003","ms":"Perintah Pindaan Akta Perbadanan Tabung Amanah Islam Brunei 2003"},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-15-2003-E-PERBADANAN-TABUNG-AMANAH-ISLAM-BRUNEI-ACT-AMENDMENT-ORDER-2003.pdf》（1 页），本次切分 2 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-15-2003-E-PERBADANAN-TABUNG-AMANAH-ISLAM-BRUNEI-ACT-AMENDMENT-ORDER-2003.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-15-2003-E-PERBADANAN-TABUNG-AMANAH-ISLAM-BRUNEI-ACT-4D698A-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Order may be cited as the Perbadanan Tabung Amanah Islam Brunei Act (Amendment) Order, 2003. Amendment of section 30 of Chapter 163."}},{"id":"BN-S-15-2003-E-PERBADANAN-TABUNG-AMANAH-ISLAM-BRUNEI-ACT-4D698A-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 30 of the Perbadanan Tabung Amanah Islam Brunei Act is amended by repealing subsection (2) and by substituting the following new subsection therefor\"(2) The accounts of the Perbadanan shall be audited annually by(a} the Auditor General; or {b) any person who has been authorised to perform the duties required by the Companies Act (Chapter 39) to be performed by an auditor, who shall be appointed annually by the Perbadanan with the approval of the 'Minister responsible for finance: Provided that where the accounts of the Perbadanan have been audited by a person appointed under paragraph {b), they may be verified by the Auditor General before a copy of the statement of those accounts is transmitted pursuant to subsection (3) to the Minister responsible for finance.\". Made this 21st. day of Muharam, 1424 Hijriah corresponding to the 24th. day of March, 2003 at Our Istana Nurul Iman, Bandar Seri Begawan, Brunei Darussalam.\n\nHIS MAJESTY\n\nTHE SULTAN AND YANG DI-PERTUAN\n\nBRUNEI DARUSSALAM"}}],"pack":"bn-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"PERBADANAN TABUNG AMANAH ISLAM BRUNEI ACT AMENDMENT ORDER 2003","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-15-2005-E-ORDER-UNDER-SECTION-152"] = {"id":"BN-S-15-2005-E-ORDER-UNDER-SECTION-152","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":3,"structureMode":"SECTION","title":{"zh":"依第 152 条作出的命令","en":"ORDER UNDER SECTION 152","orig":"ORDER UNDER SECTION 152","vi":"Sắc lệnh Điều 152","th":"คำสั่งมาตรา 152","id":"Perintah Pasal 152","ms":"Perintah Seksyen 152"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-15_2005_E-ORDER-UNDER-SECTION-152.pdf》（3 页），本次切分 3 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-15_2005_E-ORDER-UNDER-SECTION-152.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-15-2005-E-ORDER-UNDER-SECTION-152-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In exercise of the power conferred by paragraph (a) of subsection (2) of section 15 of the Land Code, His Majesty the Sultan and Yang Di-Pertuan in Council hereby prescribes the rent payable in respect of land held by entry in the Register where the area is less than 100 acres shall be at the following rates - Padi $2 per acre or part thereof Agriculture $5 per acre or part thereof Rubber $5 per acre or part thereof Residential outside the Municipal area, $10 per quarter-acre or part thereof inside the Municipal area, $50 per quarter-acre or part thereof Residential and incidental outside the Municipal area, $12.50 per commercial quarter-acre or part thereof inside the Municipal area, $62.50 per quarter-acre or part thereof Residential and commercial $125 per quarter-acre or part thereof Apartment/flats $100 per quarter-acre or part thereof Apartment/flats and commercial $125 per quarter-acre or part thereof Industrial $150 per quarter-acre or part thereof 19th. MARCH, 2005 Institutional building $62.50 per quarter-acre or part thereof Institutional building, commercial $150 per quarter-acre or part thereof and industrial Hotel $150 per quarter-acre or part thereof Petrol Station $125 per quarter-acre or part thereof Diplomatic $62.50 per quarter-acre or part thereof."}},{"id":"BN-S-15-2005-E-ORDER-UNDER-SECTION-152-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In exercise of the power conferred by paragraph (b) of subsection (2) of section 15 of the Land Code, His Majesty the Sultan and Yang Di-Pertuan in Council hereby directs the rent payable in respect of land held by entry in the Register where the area is 100 acres or more shall be at the following ratesPadi $2 per acre or part thereof Agriculture $5 per acre or part thereof Rubber $5 per acre or part thereof Residential outside the Municipal area, $10 per quarter-acre or part thereof inside the Municipal area, $50 per quarter-acre or part thereof Residential and incidental outside the Municipal area, $12.50 per commercial quarter-acre or part thereof inside the Municipal area, $62.50 per quarter-acre or part thereof Residential and commercial $125 per quarter-acre or part thereof Apartment/flats $100 per quarter-acre or part thereof Apartment/flats and commercial $125 per quarter-acre or part thereof Industrial $150 per quarter-acre or part thereof Institutional building $62.50 per quarter-acre or part thereof Institutional building, commercial $150 per quarter-acre or part thereof and industrial Hotel $150 per quarter-acre or part thereof Petrol Station $125 per quarter-acre or part thereof Diplomatic $62.50 per quarter-acre or part thereof."}},{"id":"BN-S-15-2005-E-ORDER-UNDER-SECTION-152-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Order shall be deemed to have come into force on the 22nd. April, 1999. Dated this 4th. day of Safar, 1426 Hijriah corresponding to the 15th. day of March, 2005.\n\nPEHIN ORANG KAYA SETIA PAHLAWAN DATO SERI SETIA DR. HAJI AWANG AHMAD BIN HAJI JUMAT Minister of Development, Brunei Darussalam."}}],"pack":"bn-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"ORDER UNDER SECTION 152","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
